head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40201";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — corpUsrNm, param.corpUsrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil40201.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "ipt_corpUsrNm", fn: function(){ return ((dma_pageContext.get("corpUsrNm") ?? "") !== ''); } }, { id: "c_otherwise_34", fn: function(){ return (!(((dma_pageContext.get("corpUsrNm") ?? "") !== ''))); } }, { id: "c_when_101", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "")==='11' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='13' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='15' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='21' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='22' ||
                    (dma_pageContext.get("corpUsrTpCd") ?? "")==='23' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='24' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='32' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='61' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='1E'); } }, { id: "c_when_107", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "")==='16' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='17' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='1B' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='1F' || (dma_pageContext.get("corpUsrTpCd") ?? "")==='1G'); } }, { id: "c_when_114", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "")==='12'); } }, { id: "c_when_121", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "")==='1A'); } }, { id: "c_when_128", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "")==='14'); } }, { id: "c_when_135", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "")==='19'); } }, { id: "c_when_142", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "")==='31'); } }, { id: "c_when_149", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "")==='1C'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_corpUsrNm", fn: function () { return String(String((dma_pageContext.get("corpUsrNm") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.initValue();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40201.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
