///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ChkDuplicate
 * @description Chk Duplicate 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ChkDuplicate = async function () {
    const sbmOptions = {
        id: "tx_fn_ChkDuplicate",
        method: "post",
        action: "/outer/popRegister.do?method=searchIdDuplication",
        ref: "dma_ChkDuplicateReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_ApplyJoin
 * @description Apply Join 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ApplyJoin = async function () {
    const sbmOptions = {
        id: "tx_fn_ApplyJoin",
        method: "post",
        action: "/outer/registerPersonal.do",
        ref: "dma_ApplyJoinReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name popZipCode
 * @description pop Zip Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popZipCode = async function () {
    const zipSearchURL = '/jldinf90009/jldinf90009.xml';
    scwin.setZipCode_recv(await $c.win.openPopup(zipSearchURL, { id: "zipWin", scrollbars: false, resizable: false, width: "445", height: "600", type: "pageFramePopup" }, { method: "loadInitPage" }));
};

/**
 * @method
 * @name searchLeadcomList
 * @description search Leadcom List 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchLeadcomList = function () {
    const leadcomSearchURL = '/common/leadcomList.do?method=loadInitPageForLeadcom';
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(leadcomSearchURL), { id: "leadcomWin", scrollbars: false, resizable: false, width: "600", height: "650", type: "pageFramePopup" }, {});
};

/**
 * @method
 * @name setZipCode
 * @description set Zip Code 처리
 * @param {*} _zipCode _zipCode
 * @param {*} _address _address
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode = function (_zipCode, _address) {
    $c.util.getComponent("ipt_zipcd").setValue(_zipCode);
    $c.util.getComponent("ipt_addr").setValue(_address);
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {*} _target _target
 * @returns {void}
 * @hidden N
 */
scwin.goURL = function (_target) {
    let linkUrl;
    if (_target === 'cancel') {
        linkUrl = '/';
    }
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(linkUrl));
};

/**
 * @method
 * @name chkDuplicate
 * @description chk Duplicate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkDuplicate = async function () {
    const frm = $c.util.getComponent('personalForm');
    const usrIdObj = $c.util.getComponent('ipt_usrId');
    if (await scwin.checkRequired(usrIdObj)) {
        return;
    }
    if (!await scwin.checkNotOnlyNumber(usrIdObj)) {
        return;
    }
    if (!await scwin.checkAlphaNum(usrIdObj, 6, 20)) {
        return;
    }
    $c.util.getComponent("ipt_usrId").setValue((usrIdObj.getValue()).toLowerCase());
    frm.action = '/outer/popRegister.do?method=searchIdDuplication';
    frm.target = 'duplicateWin';
    $c.win.openPopup('', { id: "duplicateWin", scrollbars: false, resizable: false, width: "360", height: "335", type: "pageFramePopup" }, {});
    await scwin.tx_fn_ChkDuplicate();
};

/**
 * @method
 * @name useUsrId
 * @description use Usr Id 처리
 * @param {String} _usrId _usrId
 * @returns {void}
 * @hidden N
 */
scwin.useUsrId = function (_usrId) {
    const frm = $c.util.getComponent('personalForm');
    $c.util.getComponent("ipt_usrId").setValue(_usrId);
    $c.util.getComponent('dma_ChkDuplicateReq').set('chkDuplicate', 'Y');
};

/**
 * @method
 * @name chkDuplicateReset
 * @description chk Duplicate Reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkDuplicateReset = function () {
    const frm = $c.util.getComponent('personalForm');
    $c.util.getComponent('dma_ChkDuplicateReq').set('chkDuplicate', 'N');
};

/**
 * @method
 * @name applyJoin
 * @description apply Join 처리
 * @param {String} _flag _flag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.applyJoin = async function (_flag) {
    const frm = $c.util.getComponent('personalForm');
    await scwin.checkPersonal();
    if (await scwin.checkRequired(frm.leadcomMbrNo)) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_usrId'))) {
        return;
    }
    if ($c.util.getComponent('dma_ChkDuplicateReq').get('chkDuplicate') !== 'Y') {
        await $c.win.alert('아이디 중복 확인을 하셔야 합니다.');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_corpUsrNm'))) {
        return;
    }
    $c.util.getComponent("ipt_corpUsrNm").setValue(String($c.util.getComponent('ipt_corpUsrNm').getValue()).replace(/\s/g, ""));
