    if (!$c.str.isEmail($c.util.getComponent('dma_ChkDuplicateReq').get('email'))) {
        return;
    }
    if (_flag === 'next') {
        frm.target = '';
        $c.util.getComponent('dma_ChkDuplicateReq').set('method', 'registerDetailInformation');
        frm.action = '/outer/registerPersonal.do';
    } else {
        frm.target = '';
        $c.util.getComponent('dma_ChkDuplicateReq').set('method', 'registerBasicInformation');
        frm.action = '/outer/registerPersonal.do';
    }
    await scwin.tx_fn_ApplyJoin();
