/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initValue = async function () {
    const uniqueCodeTitleTd = $c.util.getComponent('txt_uniqueCodeTitle');
    const uniqueCodeInputTd = $c.util.getComponent('txt_uniqueCodeInput');
    const titleStr = "회원사 코드";
    const inputStr = "<input type='text' name='leadcomMbrNo' alt='회원사코드' maxLength='5' class='form_search' size='20' value='" + dma_resultInfo.get("mktpartcNo") + "' readonly/>" + "<input type='hidden' name='isurCd'/>";
    uniqueCodeTitleTd.innerHTML = titleStr;
    uniqueCodeInputTd.innerHTML = inputStr;
    await scwin.checkPersonal();
};

/**
 * @method
 * @name checkPersonal
 * @description check Personal 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkPersonal = async function () {
    const personalChk = $c.util.getComponent('ipt_personalCheck').getValue();
    if (personalChk !== 'Y') {
        if (await $c.win.confirm("개인정보 처리방침 및 수집·이용에 동의해주시기 바랍니다.")) {
            (Promise.resolve($c.win.openPopup("/personalInfo_layer/personalInfo_layer.xml", { id: "personalInfo", width: "800", height: "700", scrollbars: false, type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("personalInfo"); this.closed = true; } });
        } else {
            return;
        }
    }
};

/**
